diff --git a/src/lib/stageTransitions.ts b/src/lib/stageTransitions.ts
@@ -0,0 +1,35 @@
+type StageAction =
+  | { type: 'move'; stageId: string }
+  | { type: 'reject'; reason: string }
+  | { type: 'hold'; until: Date };
+
+export function handleAction(action: StageAction, candidateId: string) {
+  if (action.type === 'move') {
+    return moveCandidate(candidateId, action.stageId);
+  }
+  if (action.type === 'reject') {
+    return rejectCandidate(candidateId, action.reason);
+  }
+  if (action.type === 'hold') {
+    return holdCandidate(candidateId, action.until);
+  }
+  return null;
+}
